static char *record = NULL;

/*
 * Append text to an interpreted record without exceeding its allocation.
 * Returns 0 on success and 1 when the complete text does not fit.
 */
static int append_text(char **cursor, size_t *remaining, const char *text)
{
	size_t length = strlen(text);

	if (length >= *remaining)
		return 1;
	memcpy(*cursor, text, length);
	*cursor += length;
	*remaining -= length;
	**cursor = '\0';
	return 0;
}

static inline void write_syslog(char *s)
{
	if (interpret) {
		int rc, header = 0;
		char *mptr, tbuf[64];
		size_t remaining;

		// Setup record buffer
		if (record == NULL)
			record = malloc(MAX_AUDIT_MESSAGE_LENGTH);
		if (record == NULL)
			return;

		auparse_state_t *au = auparse_init(AUSOURCE_BUFFER, s);
		if (au == NULL)
			return;
		rc = auparse_first_record(au);

		// AUDIT_EOE has no fields - drop it
		if (auparse_get_num_fields(au) == 0) {
			auparse_destroy(au);
			return;
		}

		// Now iterate over the fields and print each one
		mptr = record;
		remaining = MAX_AUDIT_MESSAGE_LENGTH;
		*mptr = '\0';
		while (rc > 0) {
			int ftype = auparse_get_field_type(au);
			const char *fname = auparse_get_field_name(au);
			const char *fval;
			switch (ftype) {
				case AUPARSE_TYPE_ESCAPED_FILE:
					fval = auparse_interpret_realpath(au);
					break;
				case AUPARSE_TYPE_SOCKADDR:
					fval =
					    auparse_interpret_sock_address(au);
					if (fval == NULL)
					    fval =
					      auparse_interpret_sock_family(au);
					break;
				default:
					fval = auparse_interpret_field(au);
					break;
			}

			if (append_text(&mptr, &remaining,
					fname ? fname : "?") ||
			    append_text(&mptr, &remaining, "=") ||
			    append_text(&mptr, &remaining,
					fval ? fval : "?") ||
			    append_text(&mptr, &remaining, " "))
				break;
			rc = auparse_next_field(au);
			if (!header && fname && strcmp(fname, "type") == 0) {
				if (append_text(&mptr, &remaining, "msg=audit("))
					break;

				time_t t = auparse_get_time(au);
				struct tm *tv = localtime(&t);
				if (tv)
					strftime(tbuf, sizeof(tbuf), "%x %T", tv);
				else
					strcpy(tbuf, "?");
				if (append_text(&mptr, &remaining, tbuf) ||
				    append_text(&mptr, &remaining, ") : "))
					break;
				header = 1;
			}
		}
		// Record is complete, dump it to syslog
		syslog(priority, "%s", record);
		auparse_destroy(au);
	} else {
		char *c = strchr(s, AUDIT_INTERP_SEPARATOR);
		if (c)
			*c = ' ';
		syslog(priority, "%s", s);
	}
}

int main(int argc, const char *argv[])
{
	char tmp[MAX_AUDIT_MESSAGE_LENGTH+1];
	struct sigaction sa;

	if (init_syslog(argc, argv))
		return 1;

	/* Register sighandlers */
	sa.sa_flags = 0;
	sigemptyset(&sa.sa_mask);
	/* Set handler for the ones we care about */
	sa.sa_handler = hup_handler;
	sigaction(SIGHUP, &sa, NULL);
	sa.sa_sigaction = term_handler;
	sa.sa_flags = SA_SIGINFO;
	sigaction(SIGTERM, &sa, NULL);

