+static int parse_int(const char *text, int *value)
+{
+	char *end;
+	long parsed;
+
+	if (text == NULL || text[0] == '\0')
+		return -EINVAL;
+
+	errno = 0;
+	parsed = strtol(text, &end, 10);
+	if (errno != 0 || end == text || *end != '\0')
+		return -EINVAL;
