+		hash ^= value & 0xff;
+		hash *= 1099511628211ULL;
+		hash ^= (value >> 8) & 0xff;
+		hash *= 1099511628211ULL;
+		hash ^= (value >> 16) & 0xff;
+		hash *= 1099511628211ULL;
+		hash ^= (value >> 24) & 0xff;
+		hash *= 1099511628211ULL;
